use anyhow :: Result ; use clap :: { Parser , Subcommand } ; use std :: path :: PathBuf ; use cargo_vendormod :: workload_processor :: process_workload_recursive ; fn run_workload_worktree (name : & str , _branch : Option < & str > , output_dir : & PathBuf) -> Result < () > { println ! ("🎯 Creating worktree for workload: {}" , name) ; let workloads = get_defined_workloads () ; if let Some (workload) = workloads . iter () . find (| w | w . name == name) { let worktree_path = output_dir . join (& workload . name) ; std :: fs :: create_dir_all (& worktree_path) ? ; let output = std :: process :: Command :: new ("git") . args (& ["worktree" , "add" , worktree_path . to_str () . unwrap ()]) . output () ? ; if output . status . success () { println ! ("✅ Worktree created at: {}" , worktree_path . display ()) ; } else { eprintln ! ("❌ Failed to create worktree: {}" , String :: from_utf8_lossy (& output . stderr)) ; } } else { eprintln ! ("❌ Unknown workload: {}" , name) ; println ! ("Available workloads:") ; for w in workloads { println ! ("  - {}" , w . name) ; } } Ok (()) }